120	
121			// Read registers and peripherals
122			// {{{
123			readi(R_ZIPREGS,   16, m_state.m_sR);
124			readi(R_ZIPUSER,   16, m_state.m_uR);
125			readi(R_ZIPSYSTEM, 20, m_state.m_p);
