129			m_state.m_sp  = (m_state.m_gie) ? (m_state.m_uR[13]):(m_state.m_sR[13]);
130			// }}}
131	
132			// Read the instructions in memory
133			// {{{
134			if (m_state.m_last_pc_valid)
135				m_state.m_imem[0].m_a = m_state.m_last_pc;
136			else
137				m_state.m_imem[0].m_a = m_state.m_pc - 4;
138			try {
