140				m_state.m_imem[0].m_valid = true;
141	
142				m_stopped_at_break = ((m_state.m_imem[0].m_d & 0xf7ffffff) == 0x77000000);
143			} catch(BUSERR be) {
144				m_state.m_imem[0].m_valid = false;
145				m_stopped_at_break = false;
146			}
147			m_state.m_imem[1].m_a = m_state.m_pc;
148			try {
149				m_state.m_imem[1].m_d = readio(m_state.m_imem[1].m_a);
150				m_state.m_imem[1].m_valid = true;
151			} catch(BUSERR be) {
152				m_state.m_imem[1].m_valid = false;
153			}
154	
155			for(int i=1; i<4; i++) {
156				if (!m_state.m_imem[i].m_valid) {
157					m_state.m_imem[i+1].m_valid = false;
158					m_state.m_imem[i+1].m_a = m_state.m_imem[i].m_a+4;
159					continue;
160				}
161				m_state.m_imem[i+1].m_a = zop_early_branch(
162						m_state.m_imem[i].m_a,
163						m_state.m_imem[i].m_d);
164				try {
165					m_state.m_imem[i+1].m_d = readio(m_state.m_imem[i+1].m_a);
166					m_state.m_imem[i+1].m_valid = true;
167				} catch(BUSERR be) {
