169				}
170			}
171			// }}}
172	
173			// Read the stack
174			// {{{
175			m_state.m_smem[0].m_a = m_state.m_sp;
176	
177			try { // Try a fast read.  Works if no bus errors
178				// {{{
179				unsigned int	buffer[5];
180				readi(m_state.m_sp, 5, buffer);
181				for(int i=0; i<5; i++) {
182					m_state.m_smem[i].m_valid = true;
183					m_state.m_smem[i].m_a = m_state.m_sp + 4*i;
184					m_state.m_smem[i].m_d = buffer[i];
185				}
186				// }}}
187			} catch(BUSERR be) {
188				// {{{
189				// Got a bus error.  Try reading each value
190				// from the stack individually.
191				for(int i=0; i<5; i++) {
192					m_state.m_smem[i].m_valid = true;
193					if (m_state.m_smem[i].m_valid)
194					try {
195						m_state.m_smem[i].m_d = readio(m_state.m_smem[i].m_a);
196						m_state.m_smem[i].m_valid = true;
197					} catch(BUSERR be) {
198						m_state.m_smem[i].m_valid = false;
199					}
200				}
201				// }}}
202			}
203			// }}}
